import math


PI = 3.141592653589793


def pow2(value):
    result = 1
    while result < value:
        result *= 2
    return result


def rot(angle):
    return complex(math.cos(angle), -math.sin(angle))


def radix2(data, inverse=False):
    n = len(data)
    if n < 1 or n & (n - 1):
        raise ValueError("radix2 requires a power-of-two length")
    values = [complex(value) for value in data]
    bits = n.bit_length() - 1
    for i in range(1, n):
        reversed_index = 0
        t = i
        for _ in range(bits):
            reversed_index = reversed_index * 2 + t % 2
            t //= 2
        if i < reversed_index:
            values[i], values[reversed_index] = values[reversed_index], values[i]
    half = n // 2
    twiddle = [rot(2 * PI * k / n) for k in range(half)]
    if inverse:
        twiddle = [factor.conjugate() for factor in twiddle]
    size = 2
    while size <= n:
        stride = n // size
        half_size = size // 2
        for start in range(0, n, size):
            for j in range(half_size):
                t = twiddle[j * stride] * values[start + j + half_size]
                u = values[start + j]
                values[start + j] = u + t
                values[start + j + half_size] = u - t
        size *= 2
    if inverse:
        values = [value / n for value in values]
    return values


def bluestein(values):
    m = len(values)
    q = pow2(2 * m - 1)
    chirp = [rot(PI * (n * n % (2 * m)) / m) for n in range(m)]
    a = [0j] * q
    b = [0j] * q
    for n in range(m):
        a[n] = values[n] * chirp[n]
        b[n] = chirp[n].conjugate()
        if n:
            b[q - n] = b[n]
    af = radix2(a)
    bf = radix2(b)
    convolution = radix2([af[k] * bf[k] for k in range(q)], inverse=True)
    return [chirp[k] * convolution[k] for k in range(m)]


def dft(values):
    if not values:
        raise ValueError("DFT of empty sequence")
    if len(values) & (len(values) - 1):
        return bluestein(values)
    return radix2(values)


def idft(values):
    if not values:
        raise ValueError("IDFT of empty sequence")
    if len(values) & (len(values) - 1):
        result = bluestein([complex(v).conjugate() for v in values])
        return [v.conjugate() / len(values) for v in result]
    return radix2(values, inverse=True)


def packed_real(values):
    n = len(values)
    if n < 4 or n & (n - 1):
        raise ValueError("packed real DFT requires power of two >= 4")
    half = n // 2
    z = [complex(values[2 * i], values[2 * i + 1]) for i in range(half)]
    transformed = radix2(z)
    result = []
    for k in range(half + 1):
        za = transformed[k % half]
        zb = transformed[(half - k) % half].conjugate()
        even = (za + zb) / 2
        odd = (za - zb) / (2j)
        result.append(even + rot(2 * PI * k / n) * odd)
    return result


def convolution(a, b):
    n = len(a) + len(b) - 1
    q = pow2(n)
    af = radix2(list(a) + [0] * (q - len(a)))
    bf = radix2(list(b) + [0] * (q - len(b)))
    result = radix2([af[k] * bf[k] for k in range(q)], inverse=True)
    return [value.real for value in result[:n]]


def chirp_z(windowed, sample_rate, low, high, points):
    m = len(windowed)
    step = (high - low) / (points - 1)
    q = pow2(m + points - 1)
    a = [0j] * q
    b = [0j] * q
    for n, sample in enumerate(windowed):
        a[n] = (sample * rot(2 * PI * low * n / sample_rate)
                * rot(PI * step * n * n / sample_rate))
    for offset in range(-(m - 1), points):
        b[offset % q] = rot(PI * step * offset * offset / sample_rate).conjugate()
    af = radix2(a)
    bf = radix2(b)
    g = radix2([af[k] * bf[k] for k in range(q)], inverse=True)
    return [rot(PI * step * j * j / sample_rate) * g[j] for j in range(points)]

import math
from pathlib import Path


def real(value):
    formatted = f"{value:.4f}"
    return "0.0000" if formatted == "-0.0000" else formatted


def fields(**items):
    return " ".join(f"{key}={real(value) if isinstance(value, float) else value}"
                    for key, value in items.items())


def write_lines(name, lines):
    target = Path("output") / name
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text("\n".join(lines) + "\n", encoding="ascii")


def write_csv(name, header, rows):
    lines = [header]
    for row in rows:
        lines.append(",".join(real(v) if isinstance(v, float) else str(v)
                              for v in row))
    write_lines(name, lines)


def shade_lines(grid, sample_rate, frame_length, band_db):
    count = len(grid)
    maximum = max(value for frame in grid for value in frame)
    shades = " .:-=+*#%@"
    lines = []
    for k in range(frame_length // 2, -1, -1):
        pixels = []
        for t in range(count):
            amplitude_db = 20 * math.log10(grid[t][k] / maximum)
            level = max(0, 9 - math.floor(-amplitude_db / band_db))
            pixels.append(shades[level])
        lines.append(f"{real(k * sample_rate / frame_length):>9} |{''.join(pixels)}|")
    return lines

import math

from fft import PI, rot


COEFFICIENTS = {
    "rectangular": (1.0,),
    "hann": (0.5, 0.5),
    "hamming": (0.54, 0.46),
    "blackman": (0.42, 0.5, 0.08),
    "flattop": (0.21557895, 0.41663158, 0.277263158, 0.083578947,
                0.006947368),
}
WINDOW_ORDER = tuple(COEFFICIENTS)


def window(name, length):
    coefficients = COEFFICIENTS[name]
    return [
        sum((-1) ** j * weight * math.cos(2 * PI * j * n / length)
            for j, weight in enumerate(coefficients))
        for n in range(length)
    ]


def figures(values, sample_rate):
    length = len(values)
    s1 = sum(values)
    s2 = sum(value * value for value in values)
    magnitude = abs(sum(values[n] * rot(PI * n / length)
                        for n in range(length)))
    enbw = length * s2 / (s1 * s1)
    return {
        "s1": s1,
        "s2": s2,
        "coherent_gain": s1 / length,
        "enbw_bins": enbw,
        "enbw_hz": enbw * sample_rate / length,
        "scalloping_db": -20 * math.log10(magnitude / s1),
    }
